 <div class="mapbox"><canvas id="minimap"></canvas></div><div class="toast" id="toast"></div>
 <div class="mobile-controls" id="touchControls"><div class="dpad"><div class="touchbtn up" data-key="w">▲</div><div class="touchbtn left" data-key="a">◀</div><div class="touchbtn down" data-key="s">▼</div><div class="touchbtn right" data-key="d">▶</div></div><div class="touchbtn actionbtn" data-action="interact">ACTION</div></div>
 <div class="overlay" id="intro"><div class="intro"><div class="kicker">A SMALL TOWN, A BIG DAY OUT</div><h1>ENNIS<br><span>at ease.</span></h1><p>Take the scenic route through the heart of County Clare. Pick up a few parcels, say hello to the neighbours, and make this lovely afternoon your own.</p><div class="rule"></div><button class="startbtn" id="start">START YOUR DAY&nbsp; ↗</button><div class="controls"><b>WASD / ARROWS</b> walk &amp; drive &nbsp;·&nbsp; <b>E</b> enter / exit &nbsp;·&nbsp; <b>SHIFT</b> jog</div></div><div class="corner">53° 17′ N &nbsp; 9° 03′ W<br>CLARE · EST. 1240</div></div>
 <script>
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mini=document.querySelector('#minimap'),mctx=mini.getContext('2d');
+const W=1360,H=1240, roadsX=[180,420,660,900,1140], roadsY=[140,380,620,860,1100], road=76;
+let vw=innerWidth,vh=innerHeight,dpr=Math.min(devicePixelRatio||1,2),camera={x:0,y:0},started=false,last=0,elapsed=0,toastTimer=0;
+const player={x:624,y:553,face:0,speed:0,inCar:false,carX:625,carY:604,carAngle:0};
+let cash=0,parcels=0,complete=false;
+const rand=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
+const landmarks=[
+ {x:244,y:198,w:95,h:78,name:'ENNIS POST OFFICE',type:'post',color:'#b8875c'},
+ {x:525,y:205,w:104,h:83,name:'THE OLD GROUND',type:'pub',color:'#a74d3e'},
+ {x:760,y:437,w:98,h:76,name:'CLARE MUSEUM',type:'museum',color:'#d2bd8a'},
+ {x:1000,y:675,w:106,h:82,name:'TEMPLE GATE',type:'church',color:'#c7c0a9'},
+ {x:280,y:675,w:100,h:78,name:'O’CONNELL SQUARE',type:'square',color:'#91a886'},
+ {x:790,y:930,w:102,h:78,name:'MARKET STREET',type:'market',color:'#d7aa69'},
+ {x:510,y:930,w:96,h:72,name:'LOCAL GROCER',type:'shop',color:'#638c71'},
+ {x:1040,y:205,w:102,h:76,name:'RIVER VIEW CAFÉ',type:'cafe',color:'#d2a66f'}
+];
+const stops=[{x:244,y:198,name:'Ennis Post Office'},{x:525,y:205,name:'The Old Ground'},{x:760,y:437,name:'Clare Museum'},{x:1000,y:675,name:'Temple Gate'}];
+const buildings=[],trees=[],cars=[];
+// Fill each town block with a distinct mix of little rooflines.
+for(let ix=0;ix<roadsX.length-1;ix++)for(let iy=0;iy<roadsY.length-1;iy++){
+ const bx=roadsX[ix]+road/2+9,by=roadsY[iy]+road/2+9,bw=roadsX[ix+1]-roadsX[ix]-road-18,bh=roadsY[iy+1]-roadsY[iy]-road-18,seed=ix*11+iy*17;
+ const lm=landmarks.find(a=>a.x>bx-10&&a.x+a.w<bx+bw+10&&a.y>by-10&&a.y+a.h<by+bh+10);
+ if(lm){buildings.push({x:lm.x,y:lm.y,w:lm.w,h:lm.h,name:lm.name,type:lm.type,color:lm.color});
+  const rest=[{x:bx+8,y:by+104,w:65,h:55},{x:bx+bw-76,y:by+bh-70,w:68,h:58}];rest.forEach((b,j)=>{if(b.x+b.w<bx+bw&&b.y+b.h<by+bh)buildings.push({...b,color:['#d3c7ab','#c6b59b'][j]})});
+ }else if((ix*3+iy*5)%9===2){for(let t=0;t<7;t++)trees.push({x:bx+20+rand(seed*12+t)*Math.max(1,bw-40),y:by+20+rand(seed*24+t)*Math.max(1,bh-40),r:8+rand(seed+t)*5});}
+ else {let n=1+Math.floor(rand(seed+50)*3);for(let j=0;j<n;j++){let cols=['#cdbfa3','#b7ab96','#d3c9b0','#b9c3b0','#c8ae92','#c3b7a5'];let ww=Math.min(70+rand(seed+j)*55,bw-24),hh=Math.min(55+rand(seed+j*3)*55,bh-24);let px=bx+12+rand(seed+j*5)*Math.max(1,bw-ww-24),py=by+12+rand(seed+j*9)*Math.max(1,bh-hh-24);buildings.push({x:px,y:py,w:ww,h:hh,color:cols[Math.floor(rand(seed+j*13)*cols.length)]});}}
+}
+for(let i=0;i<20;i++){let r=Math.floor(rand(i+100)*roadsY.length);cars.push({x:roadsX[Math.floor(rand(i+200)*roadsX.length)]+(rand(i+300)>.5?22:-22),y:roadsY[r]+(rand(i+400)>.5?25:-25),a:rand(i+500)>.5?Math.PI/2:0,color:['#b14b3f','#e1d4b8','#3d6c77','#d2a43c','#7f8980'][i%5],phase:rand(i+600)*8});}
+function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=vw*dpr;canvas.height=vh*dpr;mini.width=mini.clientWidth*dpr;mini.height=mini.clientHeight*dpr;}addEventListener('resize',resize);resize();
+function rectHit(x,y,r){return buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
+const keys={};addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e')interact();});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+document.querySelectorAll('.touchbtn[data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false));});document.querySelector('[data-action]').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
+document.querySelector('#start').onclick=()=>{started=true;document.querySelector('#intro').classList.add('hidden');last=performance.now();requestAnimationFrame(frame)};
+function notify(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
+function activeStop(){return stops[parcels]||null}
+function interact(){if(!started)return;if(player.inCar){player.inCar=false;player.x=player.carX+Math.cos(player.carAngle+Math.PI/2)*34;player.y=player.carY+Math.sin(player.carAngle+Math.PI/2)*34;player.speed=0;document.querySelector('#mode').textContent='WALKING';notify('Out for a stroll');return}if(Math.hypot(player.x-player.carX,player.y-player.carY)<54){player.inCar=true;player.speed=0;document.querySelector('#mode').textContent='IN THE CAR';notify('Your little runabout is ready');return}let target=activeStop();if(target&&Math.hypot(player.x-target.x,player.y-target.y)<66){if(parcels===0){parcels=1;notify('Parcels collected — off you go!')}else{cash+=50;parcels++;if(parcels>=stops.length){complete=true;notify('All delivered! A grand €150 for your trouble.')}else notify('Delivery done · €50 earned!')}updateMission();return}}
+function updateMission(){const title=document.querySelector('#missionTitle'),text=document.querySelector('#missionText'),bar=document.querySelector('#progress');if(!parcels){title.textContent='Pick up the parcels';text.textContent='The post office has a few deliveries for you. Pop by to collect them.';bar.style.width='0%'}else if(!complete){let s=activeStop();title.textContent=`Delivery ${parcels} of 3`;text.textContent=`Bring the next parcel to ${s.name}. Take the long way if you like.`;bar.style.width=`${(parcels/4)*100}%`}else{title.textContent='A job well done';text.textContent='All parcels delivered. Ennis is yours to explore — enjoy the afternoon.';bar.style.width='100%'}document.querySelector('#cash').textContent=`€ ${cash}`}

