function updateMission(){const title=document.querySelector('#missionTitle'),text=document.querySelector('#missionText'),bar=document.querySelector('#progress');if(!parcels){title.textContent='Pick up the parcels';text.textContent='The post office has a few deliveries for you. Pop by to collect them.';bar.style.width='0%'}else if(!complete){let s=activeStop();title.textContent=`Delivery ${parcels} of 3`;text.textContent=`Bring the next parcel to ${s.name}. Take the long way if you like.`;bar.style.width=`${(parcels/4)*100}%`}else{title.textContent='A job well done';text.textContent='All parcels delivered. Ennis is yours to explore — enjoy the afternoon.';bar.style.width='100%'}document.querySelector('#cash').textContent=`€ ${cash}`}
function rr(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function drawGround(){ctx.fillStyle='#84977d';ctx.fillRect(0,0,W,H);
 // soft town-park greens
 for(let i=0;i<30;i++){let x=rand(i+44)*W,y=rand(i+72)*H;ctx.fillStyle=i%2?'#8b9b80':'#7d9276';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(x,y,45+rand(i)*35,23+rand(i+9)*18,0,0,7);ctx.fill()}ctx.globalAlpha=1;
 // road surface and quiet sidewalks
 roadsX.forEach(x=>{ctx.fillStyle='#c2baa4';ctx.fillRect(x-road/2-9,0,road+18,H);ctx.fillStyle='#485458';ctx.fillRect(x-road/2,0,road,H);ctx.fillStyle='#d9d0b8';ctx.fillRect(x-road/2+3,0,3,H);ctx.fillRect(x+road/2-6,0,3,H);ctx.strokeStyle='#ddd0aa';ctx.lineWidth=1;ctx.setLineDash([17,15]);ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.setLineDash([])});
 roadsY.forEach(y=>{ctx.fillStyle='#c2baa4';ctx.fillRect(0,y-road/2-9,W,road+18);ctx.fillStyle='#485458';ctx.fillRect(0,y-road/2,W,road);ctx.fillStyle='#d9d0b8';ctx.fillRect(0,y-road/2+3,W,3);ctx.fillRect(0,y+road/2-6,W,3);ctx.strokeStyle='#ddd0aa';ctx.lineWidth=1;ctx.setLineDash([17,15]);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.setLineDash([])});
 // crosswalk bars and drain / pavement detail
 roadsX.forEach(x=>roadsY.forEach(y=>{ctx.fillStyle='#d9d5c6';for(let i=-3;i<=3;i++){ctx.fillRect(x-38+i*11,y-47,6,9);ctx.fillRect(x-38+i*11,y+38,6,9)}}));
 // local street-name plates
 [{x:180,y:269,t:'O’CONNELL STREET'},{x:660,y:509,t:'PARNELL STREET'},{x:900,y:749,t:'COLLEGE ROAD'},{x:780,y:140,t:'MARKET STREET'}].forEach(a=>{ctx.fillStyle='#e7e0cc';rr(ctx,a.x-2,a.y-7,4,14,1);ctx.fill();ctx.save();ctx.translate(a.x+6,a.y);ctx.rotate(-Math.PI/2);ctx.fillStyle='#303d3b';ctx.font='700 7px system-ui';ctx.fillText(a.t,0,0);ctx.restore()});}
function drawTree(t){ctx.fillStyle='#0002';ctx.beginPath();ctx.ellipse(t.x+4,t.y+7,t.r*1.05,t.r*.72,0,0,7);ctx.fill();ctx.fillStyle='#705e47';ctx.fillRect(t.x-2,t.y-1,4,9);ctx.fillStyle='#49694c';ctx.beginPath();ctx.arc(t.x,t.y-2,t.r,0,7);ctx.fill();ctx.fillStyle='#688064';ctx.beginPath();ctx.arc(t.x-3,t.y-5,t.r*.55,0,7);ctx.fill()}
function drawBuilding(b){ctx.fillStyle='#1b272355';rr(ctx,b.x+5,b.y+8,b.w,b.h,3);ctx.fill();ctx.fillStyle='#b9b09b';ctx.fillRect(b.x-2,b.y+b.h-5,b.w+4,7);ctx.fillStyle=b.color;rr(ctx,b.x,b.y,b.w,b.h,3);ctx.fill();ctx.fillStyle='#00000012';ctx.fillRect(b.x+5,b.y+5,b.w-10,7);ctx.strokeStyle='#6d665c55';ctx.lineWidth=1;ctx.strokeRect(b.x+.5,b.y+.5,b.w-1,b.h-1);
 let landmark=!!b.name;if(landmark){ctx.fillStyle=b.type==='pub'?'#57392e':b.type==='post'?'#6c4a31':'#465447';ctx.fillRect(b.x+b.w*.12,b.y+b.h*.4,b.w*.76,b.h*.22);ctx.fillStyle='#f0e2bc';ctx.font='700 7px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(b.name,b.x+b.w/2,b.y+b.h*.51);ctx.textAlign='left';ctx.textBaseline='alphabetic';
  // recognizable little front door and broad picture windows
  ctx.fillStyle='#4b4137';ctx.fillRect(b.x+b.w*.43,b.y+b.h-20,13,20);ctx.fillStyle='#819994';ctx.fillRect(b.x+9,b.y+b.h-23,13,12);ctx.fillRect(b.x+b.w-22,b.y+b.h-23,13,12);ctx.fillStyle='#d6be8d';ctx.fillRect(b.x+b.w*.2,b.y+b.h*.12,b.w*.6,3);
 }else{ctx.fillStyle='#655f56';ctx.fillRect(b.x+b.w*.22,b.y+b.h*.22,9,9);ctx.fillRect(b.x+b.w*.65,b.y+b.h*.22,9,9);ctx.fillRect(b.x+b.w*.22,b.y+b.h*.62,9,9);ctx.fillRect(b.x+b.w*.65,b.y+b.h*.62,9,9);ctx.fillStyle='#83928a';ctx.fillRect(b.x+b.w*.22,b.y+b.h*.22,9,4);ctx.fillRect(b.x+b.w*.65,b.y+b.h*.22,9,4);ctx.fillStyle='#91836c';ctx.beginPath();ctx.moveTo(b.x-4,b.y+8);ctx.lineTo(b.x+b.w*.45,b.y-7);ctx.lineTo(b.x+b.w+4,b.y+8);ctx.fill();}
}
function drawCar(x,y,a,color,hero=false){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#0004';rr(ctx,-16,-8,36,23,6);ctx.fill();ctx.fillStyle=color;rr(ctx,-17,-11,34,22,6);ctx.fill();ctx.fillStyle='#27373b';rr(ctx,-9,-8,17,16,4);ctx.fill();ctx.fillStyle='#8ba3a0';ctx.fillRect(-7,-7,7,5);ctx.fillRect(1,-7,6,5);ctx.fillStyle='#f4dd9c';ctx.fillRect(14,-7,2,4);ctx.fillRect(14,3,2,4);ctx.fillStyle='#7e3530';ctx.fillRect(-17,-7,2,4);ctx.fillRect(-17,3,2,4);if(hero){ctx.fillStyle='#d3b86e';ctx.beginPath();ctx.arc(-2,0,3,0,7);ctx.fill()}ctx.restore()}
function drawPerson(x,y,a){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(2,5,8,5,0,0,7);ctx.fill();ctx.fillStyle='#293c3d';rr(ctx,-5,-5,10,12,4);ctx.fill();ctx.fillStyle='#d4a47f';ctx.beginPath();ctx.arc(0,-6,4.2,0,7);ctx.fill();ctx.fillStyle='#e9d39a';ctx.fillRect(-3,-8,6,2);ctx.restore()}

