 else if(dx||dy){let len=Math.hypot(dx,dy);dx/=len;dy/=len;let speed=keys.shift?142:98;let nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(!rectHit(nx,player.y,8))player.x=nx;if(!rectHit(player.x,ny,8))player.y=ny;player.face=Math.atan2(dy,dx)}
