 elapsed+=dt;let mins=Math.floor(elapsed*1.35),total=16*60+42+mins;document.querySelector('#clock').textContent=`${String(Math.floor(total/60)%24).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function render(now){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);ctx.save();ctx.translate(-camera.x,-camera.y);drawGround();trees.forEach(drawTree);buildings.forEach(drawBuilding);drawTarget(now);cars.forEach((c,i)=>drawCar(c.x+Math.sin(now/500+c.phase)*1.5,c.y,c.a,c.color));drawCar(player.carX,player.carY,player.carAngle,'#c7924f',player.inCar);if(!player.inCar)drawPerson(player.x,player.y,player.face);
